<template>
  <div class="delivery-panel">
    <a-alert type="info" show-icon>项目需要分别对接两类 GitLab：交付 GitLab 保存 Jenkinsfile 与部署清单；业务源码 GitLab 读取业务仓库。Job 同步时会自动为当前项目签发只读凭据并录入对应 Jenkins。</a-alert>
    <a-card>
      <template #title><span class="card-title">项目交付仓库</span></template>
      <template #extra>
        <a-space>
          <a-button v-if="provisioned && !editingBinding" :disabled="!store.canConfigure" @click="editingBinding = true">修改绑定</a-button>
          <a-button v-if="editingBinding" @click="cancelBindingEdit">取消修改</a-button>
          <a-button :loading="loading" @click="load"><icon-refresh />刷新</a-button>
        </a-space>
      </template>
      <a-spin :loading="loading" style="width:100%">
        <a-empty v-if="!store.currentProjectKey" description="请先选择项目" />
        <template v-else>
          <a-alert v-if="!servers.length" type="warning" show-icon class="section-gap">平台尚未配置可用 GitLab 服务器。<a-link v-if="auth.canManageCredentials" @click="router.push({name:'gitlab-servers'})">前往平台管理添加</a-link></a-alert>
          <a-form :model="delivery" layout="vertical" class="gitlab-binding-form">
            <a-grid :cols="2" :col-gap="16">
              <a-grid-item><div class="binding-box delivery-binding"><div class="binding-title"><strong>交付 GitLab</strong><a-tag color="arcoblue">Jenkinsfile / 部署清单</a-tag></div><a-form-item label="GitLab 服务器" required><a-select v-model="delivery.server_key" :disabled="provisioned && !editingBinding" placeholder="选择交付 GitLab" @change="deliveryServerChanged"><a-option v-for="item in servers" :key="item.key" :value="item.key">{{ item.display_name }}</a-option></a-select></a-form-item><a-form-item label="交付根组" required extra="新项目会在此创建专属仓库；已有项目修改时会先校验仍是同一组仓库。"><a-select v-model="delivery.root_group" :disabled="(provisioned && !editingBinding) || !delivery.server_key" placeholder="选择授权根组"><a-option v-for="group in selectedServerRootGroups" :key="group" :value="group">{{ group }}</a-option></a-select></a-form-item></div></a-grid-item>
              <a-grid-item><div class="binding-box source-binding"><div class="binding-title"><strong>业务源码 GitLab</strong><a-tag color="green">项目只读凭据</a-tag></div><a-form-item label="GitLab 服务器" required><a-select v-model="delivery.source_server_key" :disabled="provisioned && !editingBinding" allow-clear placeholder="选择业务源码 GitLab" @change="sourceServerChanged"><a-option v-for="item in servers" :key="item.key" :value="item.key">{{ item.display_name }}</a-option></a-select></a-form-item><a-form-item label="业务源码授权范围" required extra="自动汇总这条 GitLab 连接配置的全部授权根组及其子组；每个根组使用独立的 Jenkins 只读凭据。"><div v-if="selectedSourceServerRootGroups.length" class="source-root-scope"><a-tag v-for="group in selectedSourceServerRootGroups" :key="group" color="green">{{ group }}</a-tag></div><a-empty v-else description="选择 GitLab 后显示授权根组" /></a-form-item></div></a-grid-item>
            </a-grid>
          </a-form>
          <div class="binding-readiness" :class="{ ready: bindingReady }">
            <div><span class="readiness-dot" /><strong>{{ bindingReady ? '仓库绑定已就绪，可直接创建服务和 Job' : '完成绑定后即可直接使用' }}</strong></div>
            <small>{{ bindingReady ? (unifiedRepository ? '统一交付仓库与业务源码 GitLab 均已绑定。' : '兼容双仓库与业务源码 GitLab 均已绑定。') : '选择交付 GitLab、业务源码 GitLab 后点击“保存并启用”。' }}</small>
          </div>
          <a-alert v-if="!delivery.source_server_key" type="warning" show-icon class="section-gap">尚未绑定业务源码 GitLab。已有交付仓库不受影响，但私有业务仓库在完成绑定前不能构建。</a-alert>
          <div class="repo-grid" :class="{ unified: unifiedRepository }">
            <div v-if="unifiedRepository" class="repo-box unified-repo"><div class="repo-icon delivery">D</div><div><strong>运维交付仓库</strong><code>{{ jenkinsfilesPath }}</code><small>同一仓库按环境路径管理 Jenkinsfile、Dockerfile、服务配置和部署清单</small></div><a-tag :color="delivery.jenkinsfiles_clone_url ? 'green' : 'gray'">{{ delivery.jenkinsfiles_clone_url ? '已创建' : '待创建' }}</a-tag><a-link v-if="delivery.jenkinsfiles_clone_url" :href="webURL(delivery.jenkinsfiles_clone_url)" target="_blank">打开</a-link></div>
            <template v-else><div class="repo-box"><div class="repo-icon pipeline">J</div><div><strong>部署流水线仓库</strong><code>{{ jenkinsfilesPath }}</code><small>按环境保存 Jenkinsfile 与 Dockerfile；与测试环境结构一致</small></div><a-tag :color="delivery.jenkinsfiles_clone_url ? 'green' : 'gray'">{{ delivery.jenkinsfiles_clone_url ? '已创建' : '待创建' }}</a-tag><a-link v-if="delivery.jenkinsfiles_clone_url" :href="webURL(delivery.jenkinsfiles_clone_url)" target="_blank">打开</a-link></div>
            <div class="repo-box"><div class="repo-icon manifest">Y</div><div><strong>部署清单仓库</strong><code>{{ manifestsPath }}</code><small>environments/dev|test|uat|prod/&lt;service&gt;/manifest.yaml</small></div><a-tag :color="delivery.manifests_clone_url ? 'green' : 'gray'">{{ delivery.manifests_clone_url ? '已创建' : '待创建' }}</a-tag><a-link v-if="delivery.manifests_clone_url" :href="webURL(delivery.manifests_clone_url)" target="_blank">打开</a-link></div></template>
          </div>
          <a-alert v-if="delivery.provision_status === 'failed'" type="error" show-icon class="section-gap">{{ delivery.provision_error }}</a-alert>
          <a-alert v-if="editingBinding" type="warning" show-icon class="section-gap">修改已有绑定时，平台会核对仓库 ID 与管理标记，不会接管或覆盖其他仓库。</a-alert>
          <a-alert v-else type="info" show-icon class="section-gap">新项目默认创建一个运维交付仓库；已有双仓库项目保持原结构，不自动迁移、不影响现有 Job。</a-alert>
          <div class="actions"><a-popconfirm v-if="delivery.server_key" content="直接清除当前项目的 GitLab 绑定。不会检查或删除 Jenkins Job、服务配置、凭据、仓库登记及 GitLab 远程仓库。" @ok="detach"><a-button status="danger" :disabled="!store.canConfigure">解除仓库绑定</a-button></a-popconfirm><span class="action-spacer" /><a-button :disabled="!delivery.server_key || editingBinding" :loading="previewing" @click="preview">预览当前仓库文件</a-button><a-popconfirm :content="provisioned ? '确认保存绑定并同步当前项目交付仓库？' : '确认保存绑定并创建当前项目专属交付仓库？'" @ok="activate"><a-button type="primary" :disabled="!store.canConfigure || !delivery.server_key || !delivery.source_server_key" :loading="provisioning">{{ provisioned ? (editingBinding ? '保存新绑定并启用' : '同步并启用') : '保存并启用' }}</a-button></a-popconfirm></div>
        </template>
      </a-spin>
    </a-card>
  </div>

  <a-drawer v-model:visible="previewVisible" width="760px" title="交付仓库变更预览" :footer="false">
    <template v-if="previewData"><a-alert type="info" show-icon>将处理 {{ previewData.repositories.length }} 个项目专属仓库、{{ previewData.files.length }} 个平台管理文件。此页不会执行写入。</a-alert><div class="preview-repos"><div v-for="repo in previewData.repositories" :key="repo.kind"><strong>{{ repo.project_path }}</strong><a-tag :color="repo.exists ? (repo.managed ? 'green' : 'orange') : 'blue'">{{ repo.exists ? (repo.managed ? '已由平台管理' : '已存在，需检查') : '将创建' }}</a-tag></div></div><a-collapse accordion><a-collapse-item v-for="file in previewData.files" :key="`${file.repository}-${file.path}`" :header="`${file.repository} / ${file.path}`"><pre class="file-preview">{{ file.content }}</pre></a-collapse-item></a-collapse></template>
  </a-drawer>
</template>

<script setup lang="ts">
import { computed, reactive, ref, watch } from 'vue';
import { useRouter } from 'vue-router';
import { Message } from '@arco-design/web-vue';
import { IconRefresh } from '@arco-design/web-vue/es/icon';
import { api } from '@/services/api';
import { useAuthStore } from '@/stores/auth';
import { usePlatformStore } from '@/stores/platform';

interface GitLabServer{key:string;display_name:string;base_url:string;root_group:string;root_groups?:string[];configured:boolean}
interface ServiceSpec{key:string;display_name:string;language:'go'|'java';runtime_version:string;source_repository:string;source_branch:string;source_credential_id:string;manifest_credential_id:string;build_command:string;build_context:string;dockerfile:string;image_repository:string;namespace:string;container_port:number;replicas:number;cpu_request:string;memory_request:string;cpu_limit:string;memory_limit:string;health_path:string}
interface Delivery{project_key:string;server_key:string;root_group:string;source_server_key:string;source_root_group:string;default_branch:string;jenkinsfiles_project_path:string;jenkinsfiles_clone_url:string;manifests_project_path:string;manifests_clone_url:string;services:ServiceSpec[];provision_status?:string;provision_error?:string}
interface Preview{repositories:{kind:string;project_path:string;exists:boolean;managed:boolean}[];files:{repository:string;path:string;content:string}[]}
const emit=defineEmits<{provisioned:[]}>();const store=usePlatformStore();const auth=useAuthStore();const router=useRouter();const loading=ref(false);const saving=ref(false);const previewing=ref(false);const provisioning=ref(false);const editingBinding=ref(false);const servers=ref<GitLabServer[]>([]);const previewVisible=ref(false);const previewData=ref<Preview|null>(null);
const emptyDelivery=():Delivery=>({project_key:store.currentProjectKey,server_key:'',root_group:'',source_server_key:'',source_root_group:'',default_branch:'main',jenkinsfiles_project_path:'',jenkinsfiles_clone_url:'',manifests_project_path:'',manifests_clone_url:'',services:[]});
const delivery=reactive<Delivery>(emptyDelivery());
const roots=(server?:GitLabServer)=>server?.root_groups?.length?server.root_groups:[server?.root_group].filter(Boolean) as string[];
const selectedServer=computed(()=>servers.value.find(item=>item.key===delivery.server_key));const selectedSourceServer=computed(()=>servers.value.find(item=>item.key===delivery.source_server_key));const selectedServerRootGroups=computed(()=>roots(selectedServer.value));const selectedSourceServerRootGroups=computed(()=>roots(selectedSourceServer.value));const provisioned=computed(()=>Boolean(delivery.jenkinsfiles_clone_url&&delivery.manifests_clone_url));const bindingReady=computed(()=>provisioned.value&&delivery.provision_status==='ready'&&Boolean(delivery.source_server_key));const unifiedRepository=computed(()=>Boolean(delivery.jenkinsfiles_project_path&&delivery.jenkinsfiles_project_path===delivery.manifests_project_path)||(!delivery.jenkinsfiles_project_path&&!delivery.manifests_project_path));const jenkinsfilesPath=computed(()=>delivery.jenkinsfiles_project_path||`${delivery.root_group||selectedServer.value?.root_group||'运维根组'}/${store.currentProjectKey||'项目'}-ops-delivery`);const manifestsPath=computed(()=>delivery.manifests_project_path||jenkinsfilesPath.value);
const scope=()=>`/api/projects/${encodeURIComponent(store.currentProjectKey)}/cicd`;
const load=async()=>{if(!store.currentProjectKey){Object.assign(delivery,emptyDelivery());servers.value=[];editingBinding.value=false;return}const revision=store.scopeRevision;loading.value=true;try{const [catalog,item]=await Promise.all([api<GitLabServer[]>(`${scope()}/gitlab-servers`),api<Delivery>(`${scope()}/delivery`)]);if(revision!==store.scopeRevision)return;servers.value=catalog.filter(server=>server.configured);Object.assign(delivery,emptyDelivery(),item,{services:item.services||[]});editingBinding.value=false;ensureSelectedRoots()}catch(error:any){if(revision===store.scopeRevision)Message.error(error.message)}finally{if(revision===store.scopeRevision)loading.value=false}};
watch(()=>store.scopeRevision,()=>void load(),{immediate:true});
function ensureSelectedRoots(){if(delivery.server_key&&!selectedServerRootGroups.value.includes(delivery.root_group))delivery.root_group=selectedServerRootGroups.value[0]||'';if(delivery.source_server_key&&!selectedSourceServerRootGroups.value.includes(delivery.source_root_group))delivery.source_root_group=selectedSourceServerRootGroups.value[0]||''}
function deliveryServerChanged(){delivery.root_group=selectedServerRootGroups.value[0]||''}
function sourceServerChanged(value:any){if(!value){delivery.source_root_group='';return}delivery.source_root_group=selectedSourceServerRootGroups.value[0]||''}
function cancelBindingEdit(){void load()}
async function persist(notify=true){if(!delivery.server_key||!delivery.root_group){Message.warning('请选择交付 GitLab 服务器和授权根组');return false}if(!delivery.source_server_key||!delivery.source_root_group){Message.warning('请选择业务源码 GitLab 服务器和授权根组');return false}saving.value=true;try{const saved=await api<Delivery>(`${scope()}/delivery`,{method:'PUT',body:JSON.stringify({server_key:delivery.server_key,root_group:delivery.root_group,source_server_key:delivery.source_server_key,source_root_group:delivery.source_root_group,services:delivery.services})});Object.assign(delivery,saved,{services:saved.services||[]});if(notify)Message.success('交付 GitLab、业务源码 GitLab及授权根组已保存');return true}catch(error:any){Message.error(error.message);return false}finally{saving.value=false}}
async function preview(){if(!(await persist(false)))return;previewing.value=true;try{previewData.value=await api<Preview>(`${scope()}/delivery/preview`,{method:'POST'});previewVisible.value=true}catch(error:any){Message.error(error.message)}finally{previewing.value=false}}
async function activate(){if(!delivery.server_key||!delivery.root_group){Message.warning('请选择交付 GitLab 服务器和授权根组');return}if(!delivery.source_server_key||!delivery.source_root_group){Message.warning('请选择业务源码 GitLab 服务器');return}provisioning.value=true;try{const result=await api<{delivery:Delivery;created_files:number;updated_files:number;deleted_files:number}>(`${scope()}/delivery/activate`,{method:'POST',body:JSON.stringify({server_key:delivery.server_key,root_group:delivery.root_group,source_server_key:delivery.source_server_key,source_root_group:delivery.source_root_group,services:delivery.services})});Object.assign(delivery,result.delivery,{services:result.delivery.services||[]});editingBinding.value=false;emit('provisioned');Message.success(`仓库绑定已启用，可直接使用；新建 ${result.created_files} 个文件，更新 ${result.updated_files} 个文件`)}catch(error:any){Message.error(error.message);await load()}finally{provisioning.value=false}}
async function detach(){try{await api(`${scope()}/delivery`,{method:'DELETE',body:JSON.stringify({confirm:store.currentProjectKey})});await load();emit('provisioned');Message.success('已直接解除仓库绑定；现有 Job、服务配置、凭据和远程仓库均已保留')}catch(error:any){Message.error(error.message)}}
const webURL=(value:string)=>value.replace(/\.git$/,'');
</script>

<style scoped>
.delivery-panel{display:flex;flex-direction:column;gap:16px}.section-gap{margin-bottom:16px}.gitlab-binding-form{margin-top:16px}.binding-box{height:100%;padding:16px 16px 2px;border:1px solid #dfe7f6;border-radius:12px;background:linear-gradient(145deg,#fff,#f7faff)}.source-binding{border-color:#ccebd7;background:linear-gradient(145deg,#fff,#f3fff7)}.binding-title{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:12px}.source-root-scope{min-height:34px;padding:6px 8px;display:flex;align-items:center;flex-wrap:wrap;gap:6px;border:1px solid #b8e3c5;border-radius:6px;background:#fff}.source-binding :deep(.arco-empty){padding:3px 0}.source-binding :deep(.arco-empty-image){display:none}.binding-readiness{display:flex;align-items:center;justify-content:space-between;gap:16px;margin:14px 0;padding:12px 14px;border:1px solid #e5e8ef;border-radius:10px;background:#f7f8fa;color:#4e5969}.binding-readiness>div{display:flex;align-items:center;gap:9px}.binding-readiness small{color:#86909c}.binding-readiness.ready{border-color:#b8e3c5;background:linear-gradient(90deg,#f2fff7,#f8fffb);color:#16723a}.readiness-dot{width:9px;height:9px;border-radius:50%;background:#c9cdd4;box-shadow:0 0 0 4px rgba(201,205,212,.22)}.binding-readiness.ready .readiness-dot{background:#00b42a;box-shadow:0 0 0 4px rgba(0,180,42,.14)}.repo-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.repo-grid.unified{grid-template-columns:1fr}.repo-box{display:grid;grid-template-columns:auto minmax(0,1fr) auto;align-items:center;gap:12px;padding:16px;border:1px solid #e5e8ef;border-radius:12px;background:linear-gradient(135deg,#fff,#f7f9ff)}.unified-repo{border-color:#c9d8ff;background:linear-gradient(135deg,#f5f8ff,#fff)}.repo-box>div:nth-child(2){display:flex;flex-direction:column;gap:5px;min-width:0}.repo-box code,.repo-box small{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.repo-box small,.primary-cell small{color:#86909c}.repo-icon{display:grid;place-items:center;width:38px;height:38px;border-radius:10px;font-weight:800}.repo-icon.pipeline{color:#ff7d00;background:#fff3e8}.repo-icon.manifest{color:#165dff;background:#e8f3ff}.repo-icon.delivery{color:#fff;background:linear-gradient(135deg,#165dff,#722ed1)}.primary-cell{display:flex;flex-direction:column;gap:4px;min-width:0}.primary-cell span,.primary-cell small{max-width:380px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.actions{display:flex;align-items:center;gap:12px;margin-top:18px}.action-spacer{flex:1}.preview-repos{display:flex;flex-direction:column;gap:8px;margin:16px 0}.preview-repos>div{display:flex;align-items:center;justify-content:space-between;padding:11px 13px;border:1px solid #e5e8ef;border-radius:8px}.file-preview{max-height:420px;overflow:auto;margin:0;padding:12px;border-radius:8px;background:#111827;color:#d1fae5;font:12px/1.6 ui-monospace,SFMono-Regular,Menlo,monospace;white-space:pre-wrap}.card-title{font-weight:600}code{font-size:12px;color:#165dff}@media(max-width:1000px){.gitlab-binding-form :deep(.arco-grid){grid-template-columns:1fr!important}.repo-grid{grid-template-columns:1fr}.binding-readiness{align-items:flex-start;flex-direction:column}.actions{flex-wrap:wrap}.action-spacer{display:none}}
</style>
